import com.varabyte.kobweb.compose.foundation.layout.Row
import com.varabyte.kobweb.compose.ui.Alignment
import com.varabyte.kobweb.compose.ui.Modifier
import com.varabyte.kobweb.compose.ui.graphics.Colors
import com.varabyte.kobweb.compose.ui.modifiers.backgroundColor
import com.varabyte.kobweb.compose.ui.modifiers.borderRadius
import com.varabyte.kobweb.compose.ui.modifiers.color
import com.varabyte.kobweb.compose.ui.modifiers.fillMaxWidth
import com.varabyte.kobweb.compose.ui.modifiers.fontSize
import com.varabyte.kobweb.compose.ui.modifiers.fontWeight
import com.varabyte.kobweb.compose.ui.modifiers.height
import com.varabyte.kobweb.compose.ui.modifiers.margin
import com.varabyte.kobweb.compose.ui.modifiers.onClick
import com.varabyte.kobweb.compose.ui.modifiers.padding
import com.varabyte.kobweb.compose.ui.modifiers.position
import com.varabyte.kobweb.compose.ui.modifiers.size
import com.varabyte.kobweb.compose.ui.modifiers.top
import com.varabyte.kobweb.compose.ui.modifiers.width
import com.varabyte.kobweb.compose.ui.modifiers.zIndex
import com.varabyte.kobweb.compose.ui.styleModifier
import com.varabyte.kobweb.compose.ui.toAttrs
import com.varabyte.kobweb.silk.components.navigation.Link
import com.varabyte.kobweb.silk.style.toModifier
import kotlinx.browser.window
import org.jetbrains.compose.web.css.Position
import org.jetbrains.compose.web.css.px
import org.jetbrains.compose.web.dom.Img
import org.jetbrains.compose.web.dom.P
import org.jetbrains.compose.web.dom.Text
import org.lennycodes.gradematewebsite.components.style.DesktopNavLinksStyle
import org.lennycodes.gradematewebsite.components.style.GradeMateColors
import org.lennycodes.gradematewebsite.components.style.NavLinkStyle
import org.lennycodes.gradematewebsite.components.style.PrimaryButtonStyle
import org.lennycodes.gradematewebsite.components.style.toRgba

@Composable
fun NavBar() {
    var menuOpen by remember { mutableStateOf(false) }

    Column(
        Modifier
            .fillMaxWidth()
            .position(Position.Sticky)
            .top(0.px)
            .zIndex(50)
            // Solid fallback for browsers without backdrop-filter support.
            .backgroundColor(GradeMateColors.Surface)
            .styleModifier {
                // Translucent surface so the blur behind is actually visible.
                property(
                    "background-color",
                    GradeMateColors.Surface.toRgba(alpha = 0.82f)
                )
                property("backdrop-filter", "saturate(180%) blur(14px)")
                property("-webkit-backdrop-filter", "saturate(180%) blur(14px)")
                property(
                    "border-bottom",
                    "1px solid ${GradeMateColors.Border35}"
                )
                property(
                    "box-shadow",
                    "0 4px 24px rgba(15, 23, 42, 0.04)"
                )
            }
    ) {

        Row(
            Modifier
                .fillMaxWidth()
                .padding(
                    topBottom = 13.px,
                    leftRight = 24.px
                ),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.SpaceBetween
        ) {

// ---------------------------------------------------------
// BRAND
// ---------------------------------------------------------
            Row(
                Modifier
                    .onClick {
                        // Navigate to home
                        window.location.hash = "home"
                    }
                    .styleModifier {
                        property("display", "inline-flex")
                        property("align-items", "center")
                        property("cursor", "pointer")
                        property("text-decoration", "none")
                        property("transition", "opacity 150ms ease")
                    }
            ) {
                // Logo
                Box(
                    Modifier
                        .size(42.px)
                        .borderRadius(13.px)
                        .backgroundColor(GradeMateColors.Primary)
                        .styleModifier {
                            property(
                                "box-shadow",
                                "0 6px 18px rgba(37, 99, 235, 0.22)"
                            )
                            property(
                                "overflow",
                                "hidden"
                            )
                            property(
                                "flex-shrink",
                                "0"
                            )
                        }
                ) {
                    Img(
                        src = "/grademate.png",
                        attrs = Modifier
                            .size(42.px)
                            .borderRadius(13.px)
                            .toAttrs()
                    )
                }

                // Brand text
                Column(
                    Modifier.margin(left = 12.px)
                ) {
                    P(
                        Modifier
                            .margin(0.px)
                            .fontSize(18.px)
                            .fontWeight(FontWeight.Bold)
                            .color(GradeMateColors.Primary)
                            .styleModifier {
                                property("letter-spacing", "-0.025em")
                                property("line-height", "1.05")
                                property("white-space", "nowrap")
                            }
                            .toAttrs()
                    ) {
                        Text("GradeMate")
                    }

                    P(
                        Modifier
                            .margin(top = 4.px)
                            .fontSize(9.px)
                            .fontWeight(FontWeight.Medium)
                            .color(GradeMateColors.TextSecondary)
                            .styleModifier {
                                property("letter-spacing", "0.14em")
                                property("line-height", "1")
                                property("white-space", "nowrap")
                            }
                            .toAttrs()
                    ) {
                        Text("SMARTER GRADING")
                    }
                }
            }



            // ---------------------------------------------------------
            // DESKTOP NAVIGATION
            // ---------------------------------------------------------
            Row(
                DesktopNavLinksStyle.toModifier(),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(8.px)
            ) {

                Link("#home", "Home", NavLinkStyle.toModifier())
                Link("#docs", "Documentation", NavLinkStyle.toModifier())
                Link("#downloads", "Downloads", NavLinkStyle.toModifier())
                Link("#contact", "Contact", NavLinkStyle.toModifier())

                // Single anchor styled as a button — no nested <a> inside <button>.
                Link(
                    path = "#downloads",
                    text = "Get GradeMate",
                    modifier = PrimaryButtonStyle
                        .toModifier()
                        .margin(left = 8.px)
                        .styleModifier {
                            property("display", "inline-flex")
                            property("align-items", "center")
                            property("justify-content", "center")

                            property("height", "42px")
                            property("box-sizing", "border-box")

                            property("padding", "0 19px")

                            property("border-radius", "10px")
                            property("text-decoration", "none")

                            property("font-size", "14px")
                            property("font-weight", "600")
                            property("line-height", "1")

                            property("color", Colors.White.toString())

                            property(
                                "box-shadow",
                                "0 5px 14px rgba(37, 99, 235, 0.20)"
                            )

                            property(
                                "transition",
                                "transform 150ms ease, box-shadow 150ms ease, background-color 150ms ease"
                            )
                        }
                )
            }

            // ---------------------------------------------------------
            // MOBILE MENU BUTTON
            // ---------------------------------------------------------
            Column(
                Modifier
                    .size(42.px)
                    .borderRadius(12.px)
                    .backgroundColor(
                        if (menuOpen) GradeMateColors.Primary
                        else GradeMateColors.Surface
                    )
                    .onClick { menuOpen = !menuOpen }
                    .styleModifier {
                        // Establishes the containing block for the absolutely-
                        // positioned X bars below.
                        property("position", "relative")
                        property(
                            "border",
                            "1px solid ${GradeMateColors.Border35}"
                        )
                        property("cursor", "pointer")
                        property(
                            "transition",
                            "background-color 180ms ease, border-color 180ms ease"
                        )
                    },
                verticalArrangement = Arrangement.Center,
                horizontalAlignment = Alignment.CenterHorizontally
            ) {

                if (!menuOpen) {
                    // Hamburger — three bars in normal flow
                    repeat(3) {
                        Box(
                            Modifier
                                .width(19.px)
                                .height(2.px)
                                .borderRadius(2.px)
                                .backgroundColor(GradeMateColors.TextPrimary)
                                .styleModifier {
                                    property("margin", "2.5px 0")
                                }
                        )
                    }
                } else {
                    // X icon — both bars absolutely centered on the button
                    Box(
                        Modifier
                            .width(20.px)
                            .height(2.px)
                            .backgroundColor(Colors.White)
                            .borderRadius(2.px)
                            .styleModifier {
                                property("position", "absolute")
                                property("top", "50%")
                                property("left", "50%")
                                property(
                                    "transform",
                                    "translate(-50%, -50%) rotate(45deg)"
                                )
                            }
                    )

                    Box(
                        Modifier
                            .width(20.px)
                            .height(2.px)
                            .backgroundColor(Colors.White)
                            .borderRadius(2.px)
                            .styleModifier {
                                property("position", "absolute")
                                property("top", "50%")
                                property("left", "50%")
                                property(
                                    "transform",
                                    "translate(-50%, -50%) rotate(-45deg)"
                                )
                            }
                    )
                }
            }
        }

        // -------------------------------------------------------------
        // MOBILE DROPDOWN
        // -------------------------------------------------------------
        if (menuOpen) {

            Column(
                Modifier
                    .fillMaxWidth()
                    .padding(
                        leftRight = 20.px,
                        topBottom = 18.px
                    )
                    .backgroundColor(GradeMateColors.Surface)
                    .styleModifier {
                        property(
                            "border-top",
                            "1px solid ${GradeMateColors.Border35}"
                        )
                        property(
                            "box-shadow",
                            "0 12px 30px rgba(15, 23, 42, 0.08)"
                        )
                        // Never taller than the viewport minus the bar itself.
                        property("max-height", "calc(100vh - 80px)")
                        property("overflow-y", "auto")
                    },
                verticalArrangement = Arrangement.spacedBy(6.px)
            ) {

                Link(
                    "#home",
                    "Home",
                    NavLinkStyle
                        .toModifier()
                        .fillMaxWidth()
                        .padding(
                            topBottom = 12.px,
                            leftRight = 14.px
                        )
                        .borderRadius(10.px)
                        .onClick { menuOpen = false }
                )

                Link(
                    "#docs",
                    "Documentation",
                    NavLinkStyle
                        .toModifier()
                        .fillMaxWidth()
                        .padding(
                            topBottom = 12.px,
                            leftRight = 14.px
                        )
                        .borderRadius(10.px)
                        .onClick { menuOpen = false }
                )

                Link(
                    "#downloads",
                    "Downloads",
                    NavLinkStyle
                        .toModifier()
                        .fillMaxWidth()
                        .padding(
                            topBottom = 12.px,
                            leftRight = 14.px
                        )
                        .borderRadius(10.px)
                        .onClick { menuOpen = false }
                )

                Link(
                    "#contact",
                    "Contact",
                    NavLinkStyle
                        .toModifier()
                        .fillMaxWidth()
                        .padding(
                            topBottom = 12.px,
                            leftRight = 14.px
                        )
                        .borderRadius(10.px)
                        .onClick { menuOpen = false }
                )

                // Single anchor styled as a button.
                Link(
                    path = "#downloads",
                    text = "Get GradeMate",
                    modifier = PrimaryButtonStyle
                        .toModifier()
                        .fillMaxWidth()
                        .margin(top = 8.px)
                        .padding(
                            topBottom = 12.px,
                            leftRight = 16.px
                        )
                        .borderRadius(10.px)
                        .fontSize(14.px)
                        .fontWeight(FontWeight.SemiBold)
                        .color(Colors.White)
                        .onClick { menuOpen = false }
                        .styleModifier {
                            property("display", "inline-flex")
                            property("align-items", "center")
                            property("justify-content", "center")
                            property("text-decoration", "none")
                        }
                )
            }
        }
    }
}