@Composable
fun DocumentationSection() {
    var selectedPlatform by remember { mutableStateOf(Platform.Android) }

    Box(
        SectionStyle
            .toModifier()
            .id("docs")
            .backgroundColor(GradeMateColors.Surface)
    ) {
        Column(
            SectionInnerStyle
                .toModifier()
                .fillMaxWidth()
        ) {

            // ---------------------------------------------------------
            // HEADER
            // ---------------------------------------------------------
            P(
                attrs = EyebrowStyle
                    .toModifier()
                    .margin(0.px)
                    .toAttrs()
            ) {
                Text("Documentation")
            }
            P(
                SectionHeadingStyle.toModifier()
                    .margin(top = 12.px, bottom = 14.px)
                    .toAttrs()
            ) {
                Text("Everything You Need to Get Started")
            }
            // ---------------------------------------------------------
            // WELCOME CARD
            // ---------------------------------------------------------
            Box(
                Modifier
                    .fillMaxWidth()
                    .margin(top = 36.px)
                    .padding(
                        topBottom = 28.px,
                        leftRight = 30.px
                    )
                    .borderRadius(18.px)
                    .backgroundColor(GradeMateColors.Background)
                    .styleModifier {
                        property(
                            "border",
                            "1px solid ${GradeMateColors.Border}"
                        )
                    }
            ) {
                Column(
                    Modifier.fillMaxWidth()
                ) {

                    P(
                        Modifier
                            .margin(0.px)
                            .fontSize(21.px)
                            .fontWeight(FontWeight.Bold)
                            .color(GradeMateColors.TextPrimary)
                            .toAttrs()
                    ) {
                        Text("Welcome to GradeMate")
                    }

                    P(
                        Modifier
                            .fillMaxWidth()
                            .margin(top = 12.px, bottom = 0.px)
                            .fontSize(15.px)
                            .lineHeight(1.8)
                            .color(GradeMateColors.TextSecondary)
                            .styleModifier {
                                property("text-align", "justify")
                                property("max-width", "900px")
                            }
                            .toAttrs()
                    ) {
                        Text(
                            "GradeMate is a comprehensive academic management platform " +
                                    "designed to streamline grading, coursework, and student " +
                                    "performance tracking. It provides powerful tools for tutors " +
                                    "to manage modules, record grades, and monitor progress, " +
                                    "while giving students a clear view of their results and " +
                                    "coursework submissions."
                        )
                    }

                    P(
                        Modifier
                            .margin(top = 14.px, bottom = 0.px)
                            .fontSize(15.px)
                            .lineHeight(1.8)
                            .color(GradeMateColors.TextSecondary)
                            .styleModifier {
                                property("text-align", "justify")
                            }
                            .toAttrs()
                    ) {
                        Text(
                            "Before installing, ensure your system meets the " +
                                    "requirements below."
                        )
                    }
                }
            }

            // ---------------------------------------------------------
            // INSTALLATION REQUIREMENTS
            // ---------------------------------------------------------
            Column(
                Modifier
                    .fillMaxWidth()
                    .margin(top = 56.px)
            ) {

                P(
                    Modifier
                        .margin(0.px)
                        .fontSize(21.px)
                        .fontWeight(FontWeight.Bold)
                        .color(GradeMateColors.TextPrimary)
                        .toAttrs()
                ) {
                    Text("Installation requirements")
                }

                P(
                    Modifier
                        .margin(top = 8.px, bottom = 0.px)
                        .fontSize(14.px)
                        .lineHeight(1.7)
                        .color(GradeMateColors.TextSecondary)
                        .styleModifier {
                            property("text-align", "justify")
                            property("max-width", "760px")
                        }
                        .toAttrs()
                ) {
                    Text(
                        "GradeMate is available across multiple platforms. " +
                                "Select your platform below to view the minimum " +
                                "operating system, storage, and hardware requirements."
                    )
                }


                // Platform selector
                Row(
                    Modifier
                        .margin(top = 22.px)
                        .gap(10.px)
                        .styleModifier {
                            property("flex-wrap", "wrap")
                        }
                ) {
                    Platform.entries.forEach { platform ->

                        val isSelected = platform == selectedPlatform

                        Box(
                            Modifier
                                .padding(
                                    topBottom = 10.px,
                                    leftRight = 20.px
                                )
                                .borderRadius(10.px)
                                .cursor(Cursor.Pointer)
                                .backgroundColor(
                                    if (isSelected) {
                                        GradeMateColors.Primary
                                    } else {
                                        GradeMateColors.Background
                                    }
                                )
                                .styleModifier {
                                    property(
                                        "border",
                                        "1px solid ${
                                            if (isSelected) {
                                                GradeMateColors.Primary
                                            } else {
                                                GradeMateColors.Border
                                            }
                                        }"
                                    )
                                    property(
                                        "transition",
                                        "all 0.2s ease"
                                    )
                                }
                                .onClick {
                                    selectedPlatform = platform
                                }
                        ) {
                            P(
                                Modifier
                                    .margin(0.px)
                                    .fontSize(14.px)
                                    .fontWeight(FontWeight.SemiBold)
                                    .color(
                                        if (isSelected) {
                                            Colors.White
                                        } else {
                                            GradeMateColors.TextSecondary
                                        }
                                    )
                                    .toAttrs()
                            ) {
                                Text(platform.label)
                            }
                        }
                    }
                }


                // Requirements card
                Column(
                    CardStyle
                        .toModifier()
                        .margin(top = 18.px)
                        .fillMaxWidth()
                        .padding(
                            topBottom = 22.px,
                            leftRight = 24.px
                        )
                        .styleModifier {
                            property("max-width", "600px")
                        }
                        .gap(16.px)
                ) {

                    P(
                        Modifier
                            .margin(0.px)
                            .fontSize(16.px)
                            .fontWeight(FontWeight.SemiBold)
                            .color(GradeMateColors.TextPrimary)
                            .toAttrs()
                    ) {
                        Text("${selectedPlatform.label} requirements")
                    }

                    requirementRow(
                        "Operating system",
                        selectedPlatform.minOs
                    )

                    requirementRow(
                        "Storage",
                        selectedPlatform.storage
                    )

                    requirementRow(
                        "Other",
                        selectedPlatform.extra
                    )
                }
            }


            // ---------------------------------------------------------
            // DOWNLOAD CTA
            // ---------------------------------------------------------
            Box(
                Modifier
                    .fillMaxWidth()
                    .margin(top = 48.px)
                    .padding(
                        topBottom = 30.px,
                        leftRight = 28.px
                    )
                    .borderRadius(18.px)
                    .backgroundColor(GradeMateColors.Primary)
            ) {
                Column(
                    Modifier.fillMaxWidth(),
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {

                    P(
                        Modifier
                            .margin(0.px)
                            .fontSize(20.px)
                            .fontWeight(FontWeight.Bold)
                            .color(Colors.White)
                            .toAttrs()
                    ) {
                        Text("Ready to get started?")
                    }

                    P(
                        Modifier
                            .margin(top = 8.px, bottom = 0.px)
                            .fontSize(14.px)
                            .lineHeight(1.6)
                            .color(Colors.White)
                            .styleModifier {
                                property("opacity", "0.9")
                                property("text-align", "center")
                            }
                            .toAttrs()
                    ) {
                        Text(
                            "Download GradeMate for your platform and start " +
                                    "managing your academic records with ease."
                        )
                    }

                    Button(
                        onClick = {},
                        modifier = SecondaryButtonStyle
                            .toModifier()
                            .margin(top = 20.px)
                    ) {
                        Link(
                            "#downloads",
                            "Download Now",
                            Modifier.color(GradeMateColors.TextPrimary)
                        )
                    }
                }
            }
        }
    }
}