// FaIcon, IconCategory, and IconSize are assumed to already be in scope here because
// they live in this same package (org.lennycodes.gradematewebsite.components). If you've
// actually put them somewhere else (e.g. a dedicated `icons` package), add the matching
// imports for FaIcon / IconCategory / IconSize.

// Hover lift for a download card. Kept as its own CssStyle (rather than one-off
// styleModifier calls on the card) so the transform/shadow only apply on :hover,
// not baked into the resting state — and so CardStyle stays reusable elsewhere
// without dragging this card-specific interaction along with it.
val DownloadCardStyle = CssStyle {
    base {
        Modifier
            .fillMaxWidth()
            .padding(28.px)
            .styleModifier {
                property("height", "100%")
                property("box-sizing", "border-box")
                property("transition", "transform 0.2s ease, box-shadow 0.2s ease")
            }
    }
    hover {
        Modifier.styleModifier {
            property("transform", "translateY(-4px)")
            property("box-shadow", "0 16px 32px rgba(0, 0, 0, 0.10)")
        }
    }
}

@Composable
fun DownloadsSection() {
    val downloads = listOf(
        DownloadOption(
            platform = "Android",
            version = "v1.4.0",
            size = "24 MB",
            accent = GradeMateColors.Secondary,
            href = "https://play.google.com/store/apps/details?id=com.lennycodes.grademate", // TODO: link to APK
            description = "Install GradeMate on your Android phone or tablet."
        ),
        DownloadOption(
            platform = "Windows",
            version = "v1.4.0",
            size = "68 MB",
            accent = GradeMateColors.Primary,
            href = "https://github.com/lennycodes2000/GradeMateWebsite/releases/download/Grademate/GradeMate-2.0.6.exe",
            description = "Get the full GradeMate desktop experience for Windows."
        ),
        DownloadOption(
            platform = "Linux",
            version = "v1.4.0",
            size = "71 MB",
            accent = GradeMateColors.TextSecondary,
            href = "https://github.com/lennycodes2000/GradeMateWebsite/releases/download/Grademate/GradeMateLinux.zip",
            description = "Run GradeMate on supported Linux distributions."
        )
    )

    Box(
        SectionStyle
            .toModifier()
            .id("downloads")
    ) {
        Column(
            SectionInnerStyle.toModifier()
        ) {

            // Section heading
            P(
                EyebrowStyle
                    .toModifier()
                    .margin(0.px)
                    .toAttrs()
            ) {
                Text("Downloads")
            }

            P(
                SectionHeadingStyle
                    .toModifier()
                    .margin(top = 10.px, bottom = 12.px)
                    .toAttrs()
            ) {
                Text("Choose your platform")
            }

            P(
                SectionSubtitleStyle
                    .toModifier()
                    .margin(0.px)
                    .styleModifier {
                        property("max-width", "620px")
                    }
                    .toAttrs()
            ) {
                Text(
                    "Download the latest version of GradeMate for your device. " +
                            "All builds are free to use."
                )
            }

            // Download cards
            // NOTE: this is a Div, not a Box. Kobweb's Box stacks every direct child
            // into the same single grid cell (it's an overlay container, like Compose's
            // Box) — with three cards as direct children that collapses them on top of
            // each other and only the last one in DOM order ends up visible. A plain Div
            // has no such stacking behavior, so the grid CSS below actually lays all
            // three out side by side / in rows as intended.
            Div(
                attrs = DownloadsGridStyle
                    .toModifier()
                    .margin(top = 40.px)
                    .styleModifier {
                        property("align-items", "stretch")
                    }
                    .toAttrs()
            ) {
                downloads.forEach { option ->

                    // OS logos (android/windows/linux) are Font Awesome "brand" glyphs,
                    // not the regular/solid set — confirm IconCategory.BRANDS is the
                    // right member name in your enum and adjust if it differs.
                    val iconName = when (option.platform) {
                        "Android" -> "android"
                        "Windows" -> "windows"
                        "Linux" -> "linux"
                        else -> "download"
                    }

                    Column(
                        CardStyle
                            .toModifier()
                            .then(DownloadCardStyle.toModifier())
                            .styleModifier {
                                property("border-top", "3px solid ${option.accent.toRgba()}")
                            }
                    ) {

                        // Platform icon — soft tinted background instead of a solid
                        // fill, so it reads as an accent rather than competing with
                        // the border-top and the button below for "loudest" color.
                        Box(
                            Modifier
                                .size(52.px)
                                .borderRadius(14.px)
                                .styleModifier {
                                    property("background-color", option.accent.toRgba(alpha = 0.14f))
                                    property("display", "flex")
                                    property("align-items", "center")
                                    property("justify-content", "center")
                                }
                        ) {
                            FaIcon(
                                name = iconName,
                                style = IconCategory.BRAND,
                                modifier = Modifier
                                    .fontSize(25.px)
                                    .color(option.accent)
                            )
                        }

                        // Platform name
                        P(
                            Modifier
                                .margin(top = 20.px, bottom = 0.px)
                                .fontSize(20.px)
                                .fontWeight(FontWeight.Bold)
                                .color(GradeMateColors.TextPrimary)
                                .toAttrs()
                        ) {
                            Text(option.platform)
                        }


                        // Description
                        P(
                            Modifier
                                .margin(top = 14.px, bottom = 0.px)
                                .fontSize(14.px)
                                .lineHeight(1.6)
                                .color(GradeMateColors.TextSecondary)
                                .styleModifier {
                                    property("overflow-wrap", "break-word")
                                }
                                .toAttrs()
                        ) {
                            Text(option.description)
                        }

                        // Download button
                        Button(
                            onClick = {},
                            modifier = PrimaryButtonStyle
                                .toModifier()
                                .margin(top = 24.px)
                                .fillMaxWidth()
                                .backgroundColor(option.accent)
                        ) {
                            Link(
                                option.href,
                                modifier = Modifier
                                    .color(Colors.White)
                                    .styleModifier {
                                        property("display", "flex")
                                        property("align-items", "center")
                                        property("justify-content", "center")
                                        property("gap", "8px")
                                        property("width", "100%")
                                        property("text-decoration", "none")
                                    }
                            ) {
                                FaIcon(
                                    name = "download",
                                    style = IconCategory.SOLID,
                                    modifier = Modifier.fontSize(14.px)
                                )

                                Text("Download")
                            }
                        }
                    }
                }
            }
        }
    }
}